const emailSolicitado = ($('Formulário de solicitação').item.json.email || '').trim().toLowerCase();
const usuarios = $json.data || [];
const usuarioEncontrado = usuarios.find(u => u.email && u.email.trim().toLowerCase() === emailSolicitado);
return {
  json: {
    emailCadastrado: !!usuarioEncontrado,
    emailSolicitado: emailSolicitado,
    usuarioId: usuarioEncontrado ? usuarioEncontrado.id : null,
    usuarioNome: usuarioEncontrado ? usuarioEncontrado.name : null
  }
};
